50→ * Deleting a label detaches it from every issue. That is a wider blast radius
 * than the other label writes, so it takes the archive permission.
 */
export async function deleteLabel(
  actor: Actor,
  orgId: OrgId,
  labelId: LabelId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "project:archive", orgResource(orgId));
60→  await labelRepo.deleteLabel(orgId, labelId);
