/** Active members and the email their user row stores, for assignee matching. */
export async function listActiveMemberEmails(
  orgId: OrgId,
): Promise<readonly { userId: UserId; email: string }[]> {
  const rows = getDb()
    .select({ userId: members.userId, email: users.email })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .all();

  return rows.map((row) => ({
    userId: row.userId as UserId,
    email: row.email,
  }));
}

