}

export interface ImportIssueWrite {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: Issue["priority"];
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  readonly labelIds: readonly LabelId[];
}

/**
 * Creates every issue in the batch, any labels that did not exist yet, and
 * the import record. One transaction: a failure leaves the project unchanged.
 */
export function insertImportedIssues(input: {
  orgId: OrgId;
  projectId: ProjectId;
  importKey: string;
  authorId: UserId;
  newLabels: readonly { name: string }[];
  rows: readonly ImportIssueWrite[];
}): { issues: Issue[]; issueIds: IssueId[] } {
  const db = getDb();

  return db.transaction((tx) => {
    const stamp = toIsoTimestamp(new Date());
    const labelIdByName = new Map<string, LabelId>();

    const existingLabels = tx
      .select()
      .from(labels)
      .where(orgPredicate(labels.orgId, input.orgId))
      .all();
    for (const label of existingLabels) {
      labelIdByName.set(label.name, label.id as LabelId);
    }

    for (const label of input.newLabels) {
      if (labelIdByName.has(label.name)) continue;
      const row = tx
        .insert(labels)
        .values({
          id: newId(),
          orgId: input.orgId,
          name: label.name,
          color: "#94a3b8",
          description: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();
      labelIdByName.set(row.name, row.id as LabelId);
    }

    const maxRow = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, input.orgId),
          eq(issues.projectId, input.projectId),
        ),
      )
      .get();
    let nextNumber = (maxRow?.value ?? 0) + 1;

    const created: Issue[] = [];

    for (const rowInput of input.rows) {
      const labelIds = rowInput.labelIds.map((id) => id);
      const resolvedIds = rowInput.labelIds.length
        ? labelIds
        : [];

      const row = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId: input.orgId,
          projectId: input.projectId,
          number: nextNumber,
          title: rowInput.title,
          description: rowInput.description,
          status: rowInput.status,
          priority: rowInput.priority,
          authorId: input.authorId,
          assigneeId: rowInput.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: rowInput.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();
      nextNumber += 1;

      const attached = resolvedIds
        .map((nameOrId) => labelIdByName.get(nameOrId) ?? nameOrId)
        .filter((id, index, all) => all.indexOf(id) === index);

      // Callers pass label *names* in labelIds for imports; resolve them.
      const finalLabelIds = rowInput.labelIds
        .map((name) => labelIdByName.get(name as string) ?? (name as LabelId))
        .filter((id, index, all) => all.indexOf(id) === index);

      void attached;

      if (finalLabelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            finalLabelIds.map((labelId) => ({
              orgId: input.orgId,
              issueId: row.id,
              labelId,
            })),
          )
          .run();
      }

      created.push(toIssue(row, finalLabelIds));
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: input.orgId,
        projectId: input.projectId,
        importKey: input.importKey,
        issueIds: JSON.stringify(created.map((issue) => issue.id)),
        createdAt: stamp,
      })
      .run();

    return {
      issues: created,
      issueIds: created.map((issue) => issue.id),
    };
  });
}

