/**
 * Turns every row of an upload into an issue, in file order.
 *
 * The import key is remembered per workspace. A second upload of a key that
 * already succeeded returns that first result and writes nothing. A refusal
 * (permission, quota, rate limit) does not record the key.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const existing = await issueRepo.findIssueImport(input.orgId, input.importKey);
  if (existing) {
    const issues = await issueRepo.findIssuesByIds(input.orgId, existing.issueIds);
    return {
      importKey: existing.importKey,
      projectId: existing.projectId,
      issues,
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const members = await memberRepo.listActiveMemberEmails(input.orgId);
  const userIdByEmail = new Map<string, UserId>();
  for (const member of members) {
    userIdByEmail.set(member.email.toLowerCase(), member.userId);
  }

  const workspaceLabels = await labelRepo.listLabels(input.orgId);
  const knownLabelNames = new Set(workspaceLabels.map((label) => label.name));

  const newLabelNames: string[] = [];
  const seenNew = new Set<string>();
  for (const row of input.rows) {
    for (const name of row.labels) {
      if (knownLabelNames.has(name) || seenNew.has(name)) continue;
      seenNew.add(name);
      newLabelNames.push(name);
    }
  }

  const written = issueRepo.insertImportedIssues({
    orgId: input.orgId,
    projectId: input.projectId,
    importKey: input.importKey,
    authorId: actor.userId,
    newLabels: newLabelNames.map((name) => ({ name })),
    rows: input.rows.map((row) => ({
      title: row.title,
      description: row.description,
      status: row.status,
      priority: row.priority,
      assigneeId:
        row.assigneeEmail === null
          ? null
          : (userIdByEmail.get(row.assigneeEmail.toLowerCase()) ?? null),
      dueAt: row.dueAt,
      labelNames: uniqueInOrder(row.labels),
    })),
  });

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: input.projectId,
    importKey: input.importKey,
    issueIds: written.issueIds,
  });

  return {
    importKey: input.importKey,
    projectId: input.projectId,
    issues: written.issues,
    replayed: false,
  };
}

function uniqueInOrder(names: readonly string[]): string[] {
  const seen = new Set<string>();
  const unique: string[] = [];
  for (const name of names) {
    if (seen.has(name)) continue;
    seen.add(name);
    unique.push(name);
  }
  return unique;
}

